fn find_max(nums: Vec<i32>) -> i32 {
    // Since nums is guaranteed non-empty, we can safely take the first element as an initial max.
    let mut max_val = nums[0];

    // Iterate over the rest of the elements, updating max_val whenever we find a larger number.
    for &num in nums.iter().skip(1) {
        if num > max_val {
            max_val = num;
        }
    }

    max_val
}

